import {
  type ContentNode,
  learnerAnchorId,
  type ParsedContentDocument,
} from "@/components/cursare/foundation/model/learner-runtime"
export interface LearnerCourseProjection {
  key: string
  title: string
  publisher: string
  description: string | null
  coverImage: string | null
  theme?: string | null
  done: number
  total: number
  percent: number
  completed: boolean
  resumeHref: string
  courseHomeHref: string
  certificateHref?: string | null
}

export interface LearnerHomeProjection<T extends { completed: boolean }> {
  primary: T | null
  active: T[]
  completed: T[]
}

export function projectLearnerHome<T extends { completed: boolean }>(
  courses: readonly T[],
): LearnerHomeProjection<T> {
  const active = courses.filter((course) => !course.completed)
  return {
    primary: active[0] ?? null,
    active: active.slice(1),
    completed: courses.filter((course) => course.completed),
  }
}

export type CurriculumItemKind = "section" | "reference"
export type CurriculumItemState = "completed" | "current" | "available" | "locked"

export interface CurriculumStepSource {
  kind: CurriculumItemKind
  id: string
  title: string
  done: boolean
  available: boolean
  current: boolean
  locked: boolean
  lockReason: "drip" | "prerequisite" | null
  unlockAt: number | null
  routeSegment: string | null
}

export interface CurriculumJourneyItem extends CurriculumStepSource {
  state: CurriculumItemState
  href: string | null
  position: number
}

export function projectCurriculumJourney(
  steps: readonly CurriculumStepSource[],
  destinationFor: (step: CurriculumStepSource) => string | null,
): CurriculumJourneyItem[] {
  const declaredCurrent = steps.findIndex((step) => step.current && !step.done && !step.locked)
  const nextAvailable = steps.findIndex((step) => step.available && !step.done && !step.locked)
  const currentIndex = declaredCurrent >= 0 ? declaredCurrent : nextAvailable

  return steps.map((step, index) => {
    const state: CurriculumItemState = step.done
      ? "completed"
      : step.locked || !step.available
        ? "locked"
        : index === currentIndex
          ? "current"
          : "available"
    const reachable = !step.locked && (step.available || step.done)
    return {
      ...step,
      current: state === "current",
      state,
      href: reachable ? destinationFor(step) : null,
      position: index + 1,
    }
  })
}

export type StudyResourceKind = "download" | "external"

export interface StudyResource {
  key: string
  kind: StudyResourceKind
  label: string
  href: string
  size: number | null
  mime: string | null
  activityId?: string | null
  sectionId?: string
}

function isSafeDownloadUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 2_048) return false
  if (value.startsWith("/") && !value.startsWith("//")) return true
  try {
    return new URL(value).protocol === "https:"
  } catch {
    return false
  }
}

function isSafeExternalUrl(value: unknown): value is string {
  if (typeof value !== "string" || value.length === 0 || value.length > 2_048) return false
  try {
    return ["https:", "http:"].includes(new URL(value).protocol)
  } catch {
    return false
  }
}

function textOf(node: ContentNode): string {
  return node.text ?? (node.content ?? []).map(textOf).join("")
}

// Only from the already-revealed document the host supplied.
export function extractStudyResources(doc: ParsedContentDocument): StudyResource[] {
  const resources: StudyResource[] = []
  const seen = new Set<string>()
  let sectionId = "section:0"

  const add = (resource: StudyResource) => {
    const identity = `${resource.kind}:${resource.href}`
    if (seen.has(identity)) return
    seen.add(identity)
    resources.push(resource)
  }

  const visit = (node: ContentNode, inheritedActivityId: string | null = null) => {
    const ownActivityId = learnerAnchorId(node)
    if (node.type === "heading" && ownActivityId) sectionId = ownActivityId
    const activityId = ownActivityId ?? inheritedActivityId
    if (node.type === "fileAttachment") {
      const href = node.attrs?.url
      if (isSafeDownloadUrl(href)) {
        const name =
          typeof node.attrs?.name === "string" && node.attrs.name.trim()
            ? node.attrs.name.trim()
            : "Download"
        add({
          key: `download:${href}`,
          kind: "download",
          label: name,
          href,
          size: typeof node.attrs?.size === "number" ? node.attrs.size : null,
          mime: typeof node.attrs?.mime === "string" ? node.attrs.mime : null,
          activityId,
          sectionId,
        })
      }
    }

    for (const mark of node.marks ?? []) {
      const href = mark.type === "link" ? mark.attrs?.href : null
      if (!isSafeExternalUrl(href)) continue
      add({
        key: `external:${href}`,
        kind: "external",
        label: textOf(node).trim() || new URL(href).hostname,
        href,
        size: null,
        mime: null,
        activityId,
        sectionId,
      })
    }

    for (const child of node.content ?? []) visit(child, activityId)
  }

  visit(doc)
  return resources
}

"use client"

import { LearnerRoot } from "@/components/cursare/foundation/runtime"
import { Button } from "@/components/cursare/ui/button"
import { MenuItem } from "@/components/cursare/ui/menu"
import {
  Sheet,
  SheetDescription,
  SheetHeader,
  SheetPanel,
  SheetPopup,
  SheetTitle,
} from "@/components/cursare/ui/sheet"
import { Download, ExternalLink, X } from "lucide-react"
import {
  createContext,
  type ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react"
import type { StudyResource } from "./study-projections"

export interface StudyToolDefinition {
  id: string
  label: string
  description: string
  icon: ReactNode
  content: ReactNode
  count?: number
}

export interface StudyToolsMessages {
  close: string
  resources: string
  resourcesDescription: string
  resourcesEmpty: string
  resourceDownload: string
  resourceExternal: string
}

interface StudyToolsContextValue {
  tools: StudyToolDefinition[]
  openTool: (id: string, trigger: HTMLElement) => void
  closeTool: () => void
}

const StudyToolsContext = createContext<StudyToolsContextValue | null>(null)

export function useCloseStudyTool() {
  return useContext(StudyToolsContext)?.closeTool
}

export function useStudyTools() {
  return useContext(StudyToolsContext)
}

export function StudyToolsMenuItems() {
  const context = useContext(StudyToolsContext)
  if (!context) return null
  return (
    <>
      {context.tools.map((tool) => (
        <MenuItem key={tool.id} onClick={(event) => context.openTool(tool.id, event.currentTarget)}>
          {tool.icon}
          <span>{tool.label}</span>
          {tool.count === undefined ? null : (
            <span className="ml-auto text-muted-foreground text-xs tabular-nums">{tool.count}</span>
          )}
        </MenuItem>
      ))}
    </>
  )
}

export function StudyToolsProvider({
  tools,
  messages,
  focusModeActive = false,
  children,
}: {
  tools: StudyToolDefinition[]
  messages: Pick<StudyToolsMessages, "close">
  focusModeActive?: boolean
  children: ReactNode
}) {
  const [activeId, setActiveId] = useState<string | null>(null)
  const [mobile, setMobile] = useState(false)
  const [wide, setWide] = useState(false)
  const triggerRef = useRef<HTMLElement | null>(null)
  const railCloseRef = useRef<HTMLButtonElement | null>(null)
  const activeTool = tools.find((tool) => tool.id === activeId) ?? null

  useEffect(() => {
    const mobileMedia = window.matchMedia("(max-width: 1023px)")
    const wideMedia = window.matchMedia("(min-width: 1536px)")
    const update = () => {
      setMobile(mobileMedia.matches)
      setWide(wideMedia.matches)
    }
    update()
    mobileMedia.addEventListener("change", update)
    wideMedia.addEventListener("change", update)
    return () => {
      mobileMedia.removeEventListener("change", update)
      wideMedia.removeEventListener("change", update)
    }
  }, [])

  const closeTool = useCallback(() => {
    setActiveId(null)
    window.setTimeout(() => triggerRef.current?.focus(), 0)
  }, [])

  const openTool = useCallback((id: string, trigger: HTMLElement) => {
    triggerRef.current = trigger
    setActiveId(id)
  }, [])

  useEffect(() => {
    if (focusModeActive) closeTool()
  }, [closeTool, focusModeActive])

  useEffect(() => {
    if (!activeTool || !wide) return
    railCloseRef.current?.focus()
    const onKeyDown = (event: KeyboardEvent) => event.key === "Escape" && closeTool()
    window.addEventListener("keydown", onKeyDown)
    return () => window.removeEventListener("keydown", onKeyDown)
  }, [activeTool, closeTool, wide])

  const context = useMemo(() => ({ tools, openTool, closeTool }), [closeTool, openTool, tools])
  return (
    <StudyToolsContext.Provider value={context}>
      <LearnerRoot
        contractKey="blocks.study-tools"
        className="learner-study-frame"
        data-context-tool-open={wide && activeTool ? true : undefined}
      >
        {children}
        {wide && activeTool ? (
          <aside
            className="learner-study-tool-rail"
            aria-labelledby="learner-study-tool-title"
            data-testid="learner-contextual-tool"
          >
            <header>
              <h2 id="learner-study-tool-title">{activeTool.label}</h2>
              <Button
                ref={railCloseRef}
                type="button"
                variant="ghost"
                aria-label={messages.close}
                onClick={closeTool}
              >
                <X />
              </Button>
            </header>
            <div className="learner-study-tool-rail-body">{activeTool.content}</div>
          </aside>
        ) : null}
      </LearnerRoot>
      <Sheet open={activeTool !== null && !wide} onOpenChange={(open) => !open && closeTool()}>
        <SheetPopup
          side={mobile ? "bottom" : "right"}
          className={
            mobile
              ? "max-h-[88dvh] rounded-t-2xl border-t-0"
              : "w-[min(32rem,calc(100vw-2rem))] max-w-none"
          }
          closeProps={{ "aria-label": messages.close }}
        >
          {activeTool ? (
            <>
              <SheetHeader className="border-b px-5 py-4">
                <SheetTitle>{activeTool.label}</SheetTitle>
                <SheetDescription className="sr-only">{activeTool.description}</SheetDescription>
              </SheetHeader>
              <SheetPanel className="px-5 py-5" data-testid="learner-contextual-tool">
                {activeTool.content}
              </SheetPanel>
            </>
          ) : null}
        </SheetPopup>
      </Sheet>
    </StudyToolsContext.Provider>
  )
}

export function StudyResourceList({
  resources,
  messages,
  onOpen,
}: {
  resources: StudyResource[]
  messages: StudyToolsMessages
  onOpen?: (resource: StudyResource) => void
}) {
  if (resources.length === 0) {
    return (
      <LearnerRoot
        as="p"
        contractKey="blocks.study-resource-list"
        className="py-8 text-center text-muted-foreground text-sm"
      >
        {messages.resourcesEmpty}
      </LearnerRoot>
    )
  }
  return (
    <LearnerRoot as="ul" contractKey="blocks.study-resource-list" className="divide-y">
      {resources.map((resource) => (
        <li key={resource.key}>
          <a
            href={resource.href}
            download={resource.kind === "download" ? resource.label : undefined}
            target={resource.kind === "external" ? "_blank" : undefined}
            rel={resource.kind === "external" ? "noopener noreferrer" : undefined}
            className="flex min-h-14 items-center gap-3 rounded-sm py-3 outline-none focus-visible:ring-2 focus-visible:ring-ring"
            onClick={() => onOpen?.(resource)}
          >
            {resource.kind === "download" ? (
              <Download className="size-4 shrink-0" aria-hidden />
            ) : (
              <ExternalLink className="size-4 shrink-0" aria-hidden />
            )}
            <span className="min-w-0 flex-1">
              <span className="block truncate font-medium text-sm">{resource.label}</span>
              <span className="text-muted-foreground text-xs">
                {resource.kind === "download"
                  ? messages.resourceDownload
                  : messages.resourceExternal}
              </span>
            </span>
          </a>
        </li>
      ))}
    </LearnerRoot>
  )
}

